    // Event dates for display only: month names in the genitive and the language's range form. uk keeps the page's own path.
    const dateForms = {
        ru: {months: ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"]},
        pl: {months: ["stycznia", "lutego", "marca", "kwietnia", "maja", "czerwca", "lipca", "sierpnia", "września", "października", "listopada", "grudnia"]},
        en: {months: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]},
    };

    // start/end: {year, month, day} or null (already validated by the page). Returns "" for uk (the page formats it).
    function formatDateRange(start, end, lang) {
        const forms = dateForms[normalizeLang(lang)];
        if (!forms || (!start && !end)) return "";
        const day = p => `${p.day} ${forms.months[p.month - 1]}`;
        if (!start || !end) return day(start || end);
        if (start.year === end.year && start.month === end.month && start.day === end.day) return day(start);
        if (start.year === end.year && start.month === end.month) return `${start.day}–${end.day} ${forms.months[end.month - 1]}`;
        if (start.year === end.year) return `${day(start)} – ${day(end)}`;
        return `${day(start)} ${start.year} – ${day(end)} ${end.year}`;
    }

    function normalizeLang(lang) {
        const key = String(lang || "uk").toLowerCase().split(/[-_]/)[0];
        return Object.hasOwn(dictionaries, key) ? key : "uk";
    }

    function pluralCategory(lang, count) {
        try {
            return new Intl.PluralRules(normalizeLang(lang)).select(Number(count) || 0);
        } catch (_) {
            return Number(count) === 1 ? "one" : "other";
        }
    }

    function formatCount(key, count, lang) {
        const numericCount = Number(count);
        const safeCount = Number.isFinite(numericCount) ? Math.max(0, Math.floor(numericCount)) : 0;
        const dict = dictionaries[normalizeLang(lang)] || dictionaries.uk;
        const forms = dict.counts[key] || dictionaries.uk.counts[key];
        if (!forms) return String(safeCount);
        const category = pluralCategory(lang, safeCount);
        const template = forms[category] || forms.other || forms.many || forms.one;
        return template.replace("{count}", String(safeCount));
    }


